const D = { density: .5, scale: 1, energy: .62, speed: 1, hue: 135, x: .5, y: .5, style: 'phosphor', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- cell grid dimensions (scale -> cell size; smaller scale = finer cells) ----
const CW = Math.max(60, Math.min(256, Math.round(200 / P.scale)));
const CH = Math.max(40, Math.min(224, Math.round(CW * height / Math.max(1, width))));
const seedI = P.seed | 0;

// deterministic uniform hash (no p5 random); Math.imul keeps the 32-bit mix exact
const gh = (i, s) => { let h = (i * 374761393 + s * 668265263 + seedI * 2654435761) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); h ^= h >>> 16; return (h >>> 0) / 4294967296; };

// ---- rule by section (Wolfram elementary rules), seed-rotated ----
const RULES = [90, 30, 110, 150, 54, 126, 60, 105, 22, 73, 45, 182];
const secI = Math.floor(K.section) % 8;
const RULE = RULES[(secI + (seedI % RULES.length)) % RULES.length];
if (S.ruleUsed !== RULE) {
  S.ruleUsed = RULE;
  S.rl = new Uint8Array(8);
  for (let n = 0; n < 8; n++) S.rl[n] = (RULE >> n) & 1;
}
const rl = S.rl;

// ---- clock -> streaming rate (rows/sec). Continuous K.t motion floor (never re-phases) ----
const sps = 4 + P.speed * 6 + K.intensity * 3;
const fp = K.t * sps;
const target = Math.floor(fp);
const frac = fp - target;

// ---- evolve one generation (toroidal), storing alive + birthing-neighborhood code ----
function evolve(prev) {
  const pa = prev.a, na = new Uint8Array(CW), nc = new Uint8Array(CW);
  let cnt = 0;
  for (let i = 0; i < CW; i++) {
    const l = pa[(i - 1 + CW) % CW], c = pa[i], r = pa[(i + 1) % CW];
    const n = (l << 2) | (c << 1) | r;
    const v = rl[n];
    na[i] = v; nc[i] = n; cnt += v;
  }
  // sustain: reseed degenerate rows so the field never blanks or floods
  if (cnt < CW * 0.03 || cnt > CW * 0.97) {
    for (let i = 0; i < CW; i++) { na[i] = gh(i, S.stepCount | 0) < (0.16 + P.density * 0.4) ? 1 : 0; nc[i] = na[i] ? ((i * 3 + (S.stepCount | 0)) & 7) : 0; }
  } else if (((S.stepCount | 0) % 41) === 0) {
    // occasional single-cell spark -> spawns a fresh triangle
    const j = ((gh(7, S.stepCount | 0) * CW) | 0) % CW; na[j] = 1;
  }
  return { a: na, c: nc };
}

// ---- (re)build the whole spacetime field on size / seed / density / rule change ----
const dBucket = Math.round(P.density * 20);
const buildSig = CW + 'x' + CH + '_' + seedI + '_' + dBucket + '_' + RULE;
if (S.buildSig !== buildSig || !S.rows) {
  S.buildSig = buildSig;
  const p = 0.15 + P.density * 0.55;
  const first = { a: new Uint8Array(CW), c: new Uint8Array(CW) };
  for (let i = 0; i < CW; i++) { first.a[i] = gh(i, 7777) < p ? 1 : 0; first.c[i] = first.a[i] ? (i & 7) : 0; }
  S.rows = new Array(CH); S.rows[0] = first;
  S.head = CH - 1; S.stepCount = target;
  for (let k = 1; k < CH; k++) S.rows[k] = evolve(S.rows[k - 1]);
  S.sig = null;
}

// ---- advance streaming (guard t0 resets, cap catch-up) ----
if (S.stepCount == null || target < S.stepCount) S.stepCount = target;
if (target - S.stepCount > CH * 1.5) {
  S.buildSig = null; // huge jump -> rebuild next check instead of grinding
} else {
  let guard = 0;
  while (S.stepCount < target && guard < 8) {
    const nr = evolve(S.rows[S.head]);
    S.head = (S.head + 1) % CH;
    S.rows[S.head] = nr;
    S.stepCount++; guard++;
  }
}

// ---- coarse buffer ----
if (!S.g || S.gw !== CW || S.gh !== CH) { S.g = createGraphics(CW, CH); S.g.pixelDensity(1); S.gw = CW; S.gh = CH; }

// ---- color: HSV -> rgb 0..255 into a shared out triple (no per-pixel alloc) ----
const OUT = [0, 0, 0];
function setHSV(o, h, s, v) {
  h = ((h % 360) + 360) % 360; const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r = c; g = x; b = 0; } else if (h < 120) { r = x; g = c; b = 0; } else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; } else if (h < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  o[0] = (r + m) * 255; o[1] = (g + m) * 255; o[2] = (b + m) * 255;
}

const style = P.style;
const eexp = 0.55 + P.energy * 0.85;
const bh = P.hue;
const colOff = Math.floor(P.x * CW);

// choose a colorer per style (age 0 = newest/bottom .. 1 = oldest/top)
let colorer;
if (style === 'ink' || style === 'ink-on-paper') {
  colorer = (alive, code, ageN) => {
    if (!alive) { setHSV(OUT, 40, 0.09, 0.87); return; }
    const dark = 0.16 + ageN * 0.30; // fresh ink darkest, dries lighter as it scrolls up
    setHSV(OUT, 232 + code * 2, 0.24, dark);
  };
} else if (style === 'amber' || style === 'amber-crt') {
  colorer = (alive, code, ageN) => {
    if (!alive) { setHSV(OUT, 26, 0.55, 0.035); return; }
    const v = Math.min(1, (0.5 + 0.5 * (1 - ageN)) * eexp);
    setHSV(OUT, 38 - ageN * 16 + code * 1.2, 0.92, v);
  };
} else if (style === 'spectral') {
  colorer = (alive, code, ageN) => {
    if (!alive) { setHSV(OUT, bh + 190, 0.6, 0.05); return; }
    const v = Math.min(1, (0.42 + 0.55 * (1 - ageN * 0.6)) * eexp);
    setHSV(OUT, bh + code * 42 + ageN * 130 + secI * 14, 0.86, v);
  };
} else if (style === 'thermal') {
  colorer = (alive, code, ageN) => {
    let heat = alive ? (0.42 + 0.55 * (1 - ageN) + code * 0.02) : (0.04 + (1 - ageN) * 0.03);
    heat = Math.min(1, heat * eexp);
    let sat = Math.min(1, 0.55 + heat * 0.55); if (heat > 0.82) sat -= (heat - 0.82) * 3.2;
    setHSV(OUT, 285 - heat * 285, Math.max(0, sat), Math.min(1, heat * 1.35 + 0.03));
  };
} else { // phosphor terminal (default) — green-on-black, age + neighborhood color
  colorer = (alive, code, ageN) => {
    if (!alive) { setHSV(OUT, bh, 0.7, 0.055); return; }
    const v = Math.min(1, (0.5 + 0.5 * (1 - ageN)) * eexp);
    setHSV(OUT, bh + (code - 3.5) * 5 + ageN * 26, Math.max(0.35, 0.9 - ageN * 0.35), v);
  };
}

// ---- render the buffer only when something visible changed (per step or live poke) ----
const sig = style + '|' + Math.round(bh) + '|' + P.energy.toFixed(2) + '|' + (S.stepCount | 0) + '|' + CW + 'x' + CH + '|' + colOff + '|' + secI;
if (S.sig !== sig) {
  S.sig = sig;
  const g = S.g; g.loadPixels(); const px = g.pixels;
  const denom = Math.max(1, CH - 1);
  for (let r = 0; r < CH; r++) {
    const ageN = (CH - 1 - r) / denom; // top (r=0) oldest -> bottom newest
    const row = S.rows[(S.head + 1 + r) % CH];
    const ra = row.a, rc = row.c;
    for (let i = 0; i < CW; i++) {
      const ci = (i + colOff) % CW;
      colorer(ra[ci], rc[ci], ageN);
      const o = 4 * (r * CW + i);
      px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
    }
  }
  g.updatePixels();
}

// ---- draw: upscale with continuous sub-row scroll (the motion floor) ----
const rowPix = height / CH;
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.g, 0, -frac * rowPix, width, height + rowPix);
pop();

// ---- CRT scanlines for phosphor / amber (static overlay, cached) ----
if (style === 'phosphor' || style === 'amber' || style === 'amber-crt') {
  if (!S.scan || S.scanH !== height) {
    S.scan = createGraphics(4, Math.max(2, height | 0)); S.scan.pixelDensity(1);
    const s = S.scan; s.loadPixels(); const pp = s.pixels;
    for (let y = 0; y < s.height; y++) { const a = (y % 3 === 0) ? 60 : 0; for (let xx = 0; xx < 4; xx++) { const o = 4 * (y * 4 + xx); pp[o] = 0; pp[o + 1] = 0; pp[o + 2] = 0; pp[o + 3] = a; } }
    s.updatePixels(); S.scanH = height;
  }
  image(S.scan, 0, 0, width, height);
}

// ---- audio reactivity ON TOP of the clk baseline (all-zero during validation) ----
if (A.bass > 0.01 || A.treble > 0.01 || A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  fill((bh + 18) % 360, 42, 100, A.bass * P.energy * 15);
  rect(0, 0, width, height);
  const gy = height * (0.62 + P.y * 0.28);
  fill((bh + 44) % 360, 34, 100, A.treble * 22);
  rect(0, gy, width, height - gy);
  blendMode(BLEND); pop();
}
